# Texts follow the editions saved in ae8/sources/raw/ and documented in ae8/sources/*.md.
# Cuts are marked with ellipses; bracketed words are clarifications. OCR slips were corrected against a
# second scan, the page image, or a second printing (each one is listed in the source's .md file).
# Copyright basis for every source is given in ae8/sources/INDEX.md (published by 1930; U.S. government work;
# UK Parliament Hansard under the Open Parliament Licence; CC BY 4.0 data; public-domain or CC BY-SA images).
VERSION = "2026-11-09c"

def P(paragraphs, attribution, translation="", footnotes=None, glossary=None, **kw):
    d = {"type": "passage", "paragraphs": paragraphs, "attribution": attribution}
    if translation: d["translation"] = translation
    if footnotes: d["footnotes"] = footnotes
    if glossary: d["glossary"] = glossary
    d.update(kw)
    return d

def item(label, paragraphs, attribution, translation="", footnotes=None, glossary=None):
    d = {"label": label, "paragraphs": paragraphs, "attribution": attribution}
    if translation: d["translation"] = translation
    if footnotes: d["footnotes"] = footnotes
    if glossary: d["glossary"] = glossary
    return d

